Definition unreg_got (m : mem) : Prop :=
  ro_cells asegs m 0x225d00 [C8 (Z_to_bv 64 0x2d4560)]
  /\ ro_cells asegs m 0x225d10 [C8 (Z_to_bv 64 0x2d65e8); C8 (Z_to_bv 64 0x2422b8); C8 (Z_to_bv 64 0x244ab8);
                               C8 (Z_to_bv 64 0x2457a8); C8 (Z_to_bv 64 0x2457b0); C8 (Z_to_bv 64 0x2457a0);
                               C8 (Z_to_bv 64 0x227e98)].

Definition unreg_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(bv_unsigned sp - 240, bv_unsigned sp); (0x242370, 0x242378);
              (XS1_LO, XS1_HI); (XS2_LO, XS2_HI); (XS3_LO, XS3_HI); (0x7771a0, 0x7771a3); (0x777140, 0x777142)] m m'
    /\ wmono asegs m m' /\ mem_inv asegs m' /\ stk asegs m' lo (bv_unsigned sp).

Lemma unreg_spec : forall ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (lo : Z) (o1 o2 o3 o4 o5 : byte),
  a0 = Z_to_bv 64 0x22aa90 -> a1 = Z_to_bv 64 1445 ->
  stk asegs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - 240 -> 0x800f0000 <= lo ->
  unreg_got m ->
  ro_cells asegs m 0x2422d0 [C4 (Z_to_bv 64 1)] ->
  rw_cells asegs m 0x242370 [C8 (Z_to_bv 64 0)] ->
  ro_cells asegs m 0x244ab8 [C8 (Z_to_bv 64 0x7fff8000)] ->
  rw_cells asegs m 0x245798 [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x24431c [C1 (Z_to_bv 8 1)] ->
  ro_cells asegs m 0x2d6660 [C8 (Z_to_bv 64 0xffffffffffffffff)] ->
  ro_cells asegs m 0x227e98 [C8 (Z_to_bv 64 0x218338)] ->
  stk asegs m XS1_LO XS1_HI -> stk asegs m XS2_LO XS2_HI -> stk asegs m XS3_LO XS3_HI ->
  gds_at m 0x22aa90 asan_gds ->
